const text = String($json?.input?.question ?? "").trim(); // /start ...
const parts = text.split(/\s+/);
const token = parts.length >= 2 ? parts[1] : null;

return [{
  json: {
    ...$json,
    token,
  }
}];

const token = $json.token;

let is_valid_format = true;

// Если токена нет — это НЕ "invalid format", это просто "missing token"
if (!token) {
  return [{
    json: {
      ...$json,
      is_valid_format: true,
      token_missing: true,
    }
  }];
}

// Если ты используешь hash (hex) — оставь так.
// Если токены у тебя типа "CEODEMO-9F3KQ2" — ЭТА проверка будет всегда false.
const isHex = /^[0-9a-fA-F]+$/.test(token);
const isLenOk = token.length >= 20;

is_valid_format = isHex && isLenOk;

return [{
  json: {
    ...$json,
    is_valid_format,
    token_missing: false,
  }
}];

const reply_text = "✅ Access granted";

const chat_id =
  $json?.meta?.chat_id ??
  $json?.telegram?.message?.chat?.id ??
  null;

return [{
  json: {
    ...$json,
    ok: true,
    code: "OK",
    chat_id,
    reply_text,
    output: {
      ...( $json.output ?? {} ),
      reply_text,
    },
  }
}];

// unified status from SQL (preferred), fallback to old fields
const status =
  $json.status ??
  $json.redeem_status ??
  (
    !$json.token ? "NO_TOKEN"
    : ($json.is_valid_format === false ? "INVALID_FORMAT"
    : "UNKNOWN")
  );

const msg = {
  NO_TOKEN: "🔒 Use: /start YOUR_TOKEN",
  INVALID_FORMAT: "⚠️ Invalid token format.",
  NOT_FOUND: "❌ Invalid token. Ask admin for a fresh /invite.",
  EXPIRED: "⏳ Token expired. Ask admin for a fresh /invite.",
  USED: "🚫 Token already used. Ask admin for a fresh /invite.",
  UNKNOWN: "⚠️ Can't redeem token. Try again later.",
};

const reply_text = msg[status] || msg.UNKNOWN;

const chat_id =
  $json?.meta?.chat_id ??
  $json?.telegram?.message?.chat?.id ??
  null;

return [{
  json: {
    ...$json,
    ok: false,
    code: status,
    chat_id,
    output: {
      ...( $json.output ?? {} ),
      reply_text,
    },
  }
}];
